			additionalProperties: false,
		},
		execute: async (_toolCallId: string, params: unknown) => {
			const ids = Array.isArray((params as { ids?: unknown })?.ids)
				? (params as { ids: unknown[] }).ids.filter((id): id is string => typeof id === "string")
				: [];
			const result = controller.activate(ids);
			const lines = ["# Capability activation"];
			if (result.activated.length) lines.push(`- activated: ${result.activated.join(", ")}`);
			if (result.alreadyActive.length) lines.push(`- already active: ${result.alreadyActive.join(", ")}`);
			for (const item of result.unavailable) lines.push(`- unavailable ${item.id}: ${item.reason}`);
			if (result.unknown.length) lines.push(`- unknown: ${result.unknown.join(", ")}`);
			return {
				content: [{ type: "text", text: lines.join("\n") }],
				details: { tool: "activate_capabilities", ...result },
			};
		},
	} as AgentTool;
}

export class KeatingCapabilityController {
	private environment: CapabilityEnvironment;
	private allTools: AgentTool[] = [];
	private readonly active = new Set<KeatingCapabilityId>();
	private listener?: (tools: AgentTool[]) => void;
	private readonly activationTool: AgentTool;

	constructor(environment: CapabilityEnvironment = {}) {
		this.environment = environment;
		this.activationTool = activationTool(this);
	}

	setListener(listener: (tools: AgentTool[]) => void): void {
		this.listener = listener;
	}

	setEnvironment(environment: CapabilityEnvironment): void {
		this.environment = environment;
		this.dropUnavailableCapabilities();
		this.notify();
	}

	setAllTools(tools: AgentTool[]): AgentTool[] {
		this.allTools = [...tools];
		const selected = this.tools();
		this.listener?.(selected);
		return selected;
	}

	catalog(): CapabilityBundle[] {
		return buildCapabilityCatalog(this.environment);
	}

	activeIds(): KeatingCapabilityId[] {
		return [...this.active];
	}

	activate(ids: string[]): CapabilityActivationResult {
		const catalog = new Map(this.catalog().map((bundle) => [bundle.id, bundle]));
		const result: CapabilityActivationResult = { activated: [], alreadyActive: [], unavailable: [], unknown: [] };
		for (const rawId of ids) {
			const bundle = catalog.get(rawId as KeatingCapabilityId);
			if (!bundle) {
				result.unknown.push(rawId);
				continue;
			}
			if (bundle.availability !== "available") {
				result.unavailable.push({ id: bundle.id, reason: bundle.reason ?? "Capability is not available." });
				continue;
			}
			if (this.active.has(bundle.id)) result.alreadyActive.push(bundle.id);
			else {
				this.active.add(bundle.id);
				result.activated.push(bundle.id);
			}
		}
		if (result.activated.length) this.notify();
		return result;
	}

	tools(): AgentTool[] {
		const activeToolNames = new Set(BASELINE_TEACHING_TOOLS);
		for (const bundle of this.catalog()) {
			if (this.active.has(bundle.id) && bundle.availability === "available") {
				for (const name of bundle.tools) activeToolNames.add(name);
			}
		}
		return [this.activationTool, ...this.allTools.filter((tool) => activeToolNames.has(tool.name))];
	}

	private dropUnavailableCapabilities(): void {
		const catalog = new Map(this.catalog().map((bundle) => [bundle.id, bundle]));
		for (const id of this.active) {
			if (catalog.get(id)?.availability !== "available") this.active.delete(id);
		}
	}

	private notify(): void {
		this.listener?.(this.tools());
	}
}
import type { AgentTool } from "@earendil-works/pi-agent-core";
import type { KeatingAgentRuntimeConfig } from "../agent-runtime";
import type { BenchSessionSample, BrowserLearnerOutcome } from "../core";
import type { WebSpeechSettings } from "../speech";

export interface KeatingToolsOptions {
	agentRuntime?: KeatingAgentRuntimeConfig;
	speech?: {
		settings: WebSpeechSettings;
		getApiKey: (provider: string) => Promise<string | undefined>;
	};
	setSystemPrompt?: (basePrompt: string) => void;
	/** Loads stored chat sessions so benchmarks can mine real transcripts and attribute signals to the model that taught them. */
	getSessionSamples?: () => Promise<BenchSessionSample[]>;
}

export type OutcomeCollector = () => Promise<BrowserLearnerOutcome[]>;

export interface ToolRegistry {
	has(name: string): boolean;
	invoke(name: string, params: Record<string, unknown>): Promise<string>;
}

/** Create a Pi-compatible tool with Keating's text-result contract. */
export function createTool(
	name: string,
	description: string,
	parameters: Record<string, unknown>,
	execute: (params: Record<string, unknown>) => Promise<string>,
	required?: string[],
): AgentTool {
	return {
		name,
		label: name,
		description,
		parameters: {
			type: "object",
			properties: parameters,
			...(required?.length ? { required } : {}),
			additionalProperties: false,
		},
		execute: async (_toolCallId: string, params: Record<string, unknown>) => {
			const result = await execute(params as Record<string, unknown>);
			return {
				content: [{ type: "text", text: result }],
				details: { tool: name },
			};
		},
	} as unknown as AgentTool;
}

export function createToolRegistry(tools: AgentTool[]): ToolRegistry {
	return {
		has: (name) => tools.some((candidate) => candidate.name === name),
		invoke: async (name, params) => {
			const tool = tools.find((candidate) => candidate.name === name);
			if (!tool) return `Capability unavailable: ${name} is not connected in this runtime.`;
			const result = await (tool.execute as any)(`keating-composed-${name}`, params, undefined, () => {});
			const content = (result as { content?: Array<{ type?: string; text?: string }> })?.content;
			return Array.isArray(content)
				? content.filter((item) => item?.type === "text" && typeof item.text === "string").map((item) => item.text).join("\n")
				: String(result ?? "");
		},
	};
}
import { describe, expect, it } from "bun:test";
import type { AgentTool } from "@earendil-works/pi-agent-core";
import { DEFAULT_AGENT_RUNTIME_CONFIG } from "../keating/agent-runtime";
import {
	buildCapabilityCatalog,
	KeatingCapabilityController,
} from "../keating/capabilities";

const tool = (name: string) => ({ name } as AgentTool);

describe("capability registry", () => {
	it("does not expose optional schemas until a bundle is active", () => {
		const controller = new KeatingCapabilityController({ runtime: DEFAULT_AGENT_RUNTIME_CONFIG });
		controller.setAllTools([tool("quiz"), tool("ask_user_question"), tool("learner_state"), tool("inspect_learning_context"), tool("generate_image"), tool("evaluate_teaching"), tool("workspace_exec")]);

		expect(controller.tools().map((item) => item.name)).toEqual(["activate_capabilities", "quiz"]);
		controller.activate(["learner-details", "media", "improvement"]);
		expect(controller.tools().map((item) => item.name)).toEqual([
			"activate_capabilities",
			"quiz",
			"inspect_learning_context",
			"generate_image",
			"evaluate_teaching",
		]);
	});

	it("keeps runtime-impossible bundles discoverable without exposing their tools", () => {
		const controller = new KeatingCapabilityController({ runtime: DEFAULT_AGENT_RUNTIME_CONFIG });
		controller.setAllTools([tool("bash")]);
		const result = controller.activate(["workspace", "not-real"]);

		expect(result.activated).toEqual([]);
		expect(result.unavailable[0]?.id).toBe("workspace");
		expect(result.unknown).toEqual(["not-real"]);
		expect(controller.tools().map((item) => item.name)).toEqual(["activate_capabilities"]);
	});

	it("marks workspace and voice availability from the live environment", () => {
		const catalog = buildCapabilityCatalog({
			runtime: {
				...DEFAULT_AGENT_RUNTIME_CONFIG,
				projectFilesEndpoint: "/api/project-files",
				capabilities: { ...DEFAULT_AGENT_RUNTIME_CONFIG.capabilities, hostProjectAccess: true },
			},
			speechEnabled: true,
		});

		expect(catalog.find((bundle) => bundle.id === "workspace")?.availability).toBe("available");
		expect(catalog.find((bundle) => bundle.id === "workspace")?.tools).toEqual(["workspace_inspect"]);
		expect(catalog.find((bundle) => bundle.id === "voice")?.availability).toBe("available");
	});

	it("exposes only consolidated workspace schemas supported by the runtime", () => {
		const inspectOnly = buildCapabilityCatalog({
			runtime: {
				...DEFAULT_AGENT_RUNTIME_CONFIG,
				projectFilesEndpoint: "/api/project-files",
			},
		}).find((bundle) => bundle.id === "workspace");
		const attached = buildCapabilityCatalog({
			runtime: {
				...DEFAULT_AGENT_RUNTIME_CONFIG,
				projectFilesEndpoint: "/api/project-files",
				localExecEndpoint: "/api/local-exec",
			},
		}).find((bundle) => bundle.id === "workspace");

		expect(inspectOnly?.tools).toEqual(["workspace_inspect"]);
		expect(attached?.tools).toEqual(["workspace_inspect", "workspace_exec", "workspace_change"]);
	});

	it("updates the live tool set after activating multiple bundles", () => {
		const controller = new KeatingCapabilityController({ runtime: DEFAULT_AGENT_RUNTIME_CONFIG });
		const updates: string[][] = [];
		controller.setListener((tools) => updates.push(tools.map((item) => item.name)));
		controller.setAllTools([tool("quiz"), tool("generate_image"), tool("evaluate_teaching")]);
		controller.activate(["media", "improvement"]);

		expect(updates.at(-1)).toEqual(["activate_capabilities", "quiz", "generate_image", "evaluate_teaching"]);
	});
});

