	if (answers.length === 1 && !answers[0]?.header) return answers[0]?.answer ?? "";
	return answers
		.map((answer) => `- ${answer.header ? `${answer.header}: ` : ""}${answer.question}: ${answer.answer}`)
		.join("\n");
}

