162	export class KeatingCapabilityController {
163		private environment: CapabilityEnvironment;
164		private allTools: AgentTool[] = [];
165		private readonly active = new Set<KeatingCapabilityId>();
166		private listener?: (tools: AgentTool[]) => void;
167		private readonly activationTool: AgentTool;
168	
169		constructor(environment: CapabilityEnvironment = {}) {
170			this.environment = environment;
171			this.activationTool = activationTool(this);
172		}
173	
174		setListener(listener: (tools: AgentTool[]) => void): void {
175			this.listener = listener;
176		}
177	
178		setEnvironment(environment: CapabilityEnvironment): void {
179			this.environment = environment;
180			this.dropUnavailableCapabilities();
181			this.notify();
182		}
183	
184		setAllTools(tools: AgentTool[]): AgentTool[] {
185			this.allTools = [...tools];
186			const selected = this.tools();
187			this.listener?.(selected);
188			return selected;
189		}
190	
191		catalog(): CapabilityBundle[] {
192			return buildCapabilityCatalog(this.environment);
193		}
194	
195		activeIds(): KeatingCapabilityId[] {
196			return [...this.active];
197		}
198	
199		activate(ids: string[]): CapabilityActivationResult {
200			const catalog = new Map(this.catalog().map((bundle) => [bundle.id, bundle]));
201			const result: CapabilityActivationResult = { activated: [], alreadyActive: [], unavailable: [], unknown: [] };
202			for (const rawId of ids) {
203				const bundle = catalog.get(rawId as KeatingCapabilityId);
204				if (!bundle) {
205					result.unknown.push(rawId);
206					continue;
207				}
208				if (bundle.availability !== "available") {
209					result.unavailable.push({ id: bundle.id, reason: bundle.reason ?? "Capability is not available." });
210					continue;
211				}
212				if (this.active.has(bundle.id)) result.alreadyActive.push(bundle.id);
213				else {
214					this.active.add(bundle.id);
215					result.activated.push(bundle.id);
216				}
217			}
218			if (result.activated.length) this.notify();
219			return result;
220		}
