 74	function preserveRegistrationOrder(groups: AgentTool[][]): AgentTool[] {
 75		const tools = groups.flat();
 76		const byName = new Map(tools.map((tool) => [tool.name, tool]));
 77		const ordered = TOOL_REGISTRATION_ORDER.flatMap((name) => {
 78			const tool = byName.get(name);
 79			if (!tool) return [];
 80			byName.delete(name);
 81			return [tool];
 82		});
 83		return [...ordered, ...byName.values()];
 84	}
