 86	export async function createKeatingTools(
 87		storage: KeatingStorage,
 88		options: KeatingToolsOptions = {},
 89	): Promise<AgentTool[]> {
 90		const collectRealOutcomes = createOutcomeCollector(storage, options.getSessionSamples);
 91		const tools = preserveRegistrationOrder([
 92			createWorkspaceTools(options),
 93			createMediaTools(storage),
 94			createTeachingTools(storage),
 95			createAssessmentTools(storage, collectRealOutcomes),
 96			createImprovementTools(storage, options, collectRealOutcomes),
 97		]);
 98	
 99		const registry = createToolRegistry(tools);
100		tools.push(
101			...createLearnerContextCapabilityTools(registry),
102			...createImprovementCapabilityTools(registry),
103			...createWorkspaceCapabilityTools(registry),
104		);
105	
106		if (options.speech?.settings.enabled) {
107			tools.push(createSpeechTool(options.speech.settings, options.speech.getApiKey));
108		}
109	
110		return tools;
111	}
